import lens, os, re

hits = lens.grep_ast(pattern="$X.expect($MSG)", lang="rust")
rows = hits.get("hits", hits) if isinstance(hits, dict) else hits

def excluded_line_ranges(lines):
    # Brace-range exclusion for every #[cfg(test)] mod/fn block (1-based line
    # numbers), not a first-occurrence line-cut -- a file can have more than
    # one such block.
    ranges = []
    i, n = 0, len(lines)
    while i < n:
        if re.match(r'^\s*#\[cfg\(test\)\]\s*$', lines[i]):
            j = i + 1
            while j < n and re.match(r'^\s*#\[', lines[j]):
                j += 1
            if j < n and re.search(r'\b(mod|fn)\b', lines[j]):
                depth, started, k = 0, False, j
                while k < n:
                    depth += lines[k].count('{') - lines[k].count('}')
                    if '{' in lines[k]:
                        started = True
                    if started and depth <= 0:
                        break
                    k += 1
                ranges.append((i + 1, k + 1))
                i = k + 1
                continue
        i += 1
    return ranges

ranges_cache = {}
def ranges_for(path):
    if path not in ranges_cache:
        lines = open(os.path.join("../..", path), encoding="utf-8").read().split("\n")
        ranges_cache[path] = excluded_line_ranges(lines)
    return ranges_cache[path]

def in_ranges(line, ranges):
    return any(s <= line <= e for s, e in ranges)

count = 0
for h in rows:
    path = h.get("path", "")
    line = h.get("line", 0)
    if not path.startswith("src/"):
        continue
    if in_ranges(line, ranges_for(path)):
        continue
    count += 1

print(f"non-test .expect() call sites in src/ (AST-matched): {count}")
